// TIMER -----
void init_time3(){
    // Señal de reloj para el timer
    RCC->APB1ENR &= ~(RCC_APB1ENR_TIM3EN); // Limpiar la posición
    RCC->APB1ENR |= RCC_APB1ENR_TIM3EN; // Activar la señal de reloj

    TIM3->CNT = 0; // Reiniciando el contador
    TIM3->PSC = (1600-1); // Divisor por 1600
    TIM3->ARR = (2500-1); // Para generar un evento update cada 0.25 s

    TIM3->CR1 &= ~(0x3 << TIM_CR1_CKD_Pos); // Limpiamos, dejar la señal de reloj complet
    TIM3->CR1 &= ~(TIM_CR1_ARPE); // Limpiamos la posición
    TIM3->CR1 |= (TIM_CR1_ARPE); // Activando el preload para el ARR
    TIM3->CR1 &= ~TIM_CR1_DIR; // Limpiando, contador de forma ascendente

    TIM3->DIER |= TIM_DIER_UIE; // Activando la interrupción

    // Configuramos el NVIC 
    
    // linea 102 stm32f411xe.h
    NVIC_EnableIRQ(TIM3_IRQn); // Registrar la interrupción TIM3 en el NVIC

    TIM3->CR1 |= TIM_CR1_CEN; // Activamos el contador

}

